// Local test main — runs the first test case
// Usage: ./batch_matmul_max_sum_custom

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include "acl/acl.h"

#ifndef TENSOR_GROUP_INFO_DEFINED
#define TENSOR_GROUP_INFO_DEFINED
// Dtype enum for TensorInfo.dtype:
// 0=float32 1=float16 2=bfloat16 3=int8 4=int16 5=int32 6=int64
// 7=uint8 8=uint16 9=uint32 10=uint64 11=bool
struct TensorInfo {
    const int64_t* shape;
    int64_t numDims;
    int32_t dtype;
};
struct TensorGroupInfo {
    const TensorInfo* tensors;
    int64_t numTensors;
};
#endif

#include <vector>
#include "data_utils.h"

#define ACL_CHECK(expr) do { aclError _ret = (expr); if (_ret != 0) { fprintf(stderr, "[ERROR] %s failed at %s:%d, ret=%d\n", #expr, __FILE__, __LINE__, _ret); return 1; } } while(0)
#define FILE_CHECK(expr) do { if (!(expr)) { fprintf(stderr, "[ERROR] File I/O failed at %s:%d\n", __FILE__, __LINE__); return 1; } } while(0)

#include "kernel.asc"

int main()
{
    int32_t deviceId = 0;
    int64_t availableCoreNum = 0;
    aclrtStream stream = nullptr;

    ACL_CHECK(aclInit(nullptr));
    ACL_CHECK(aclrtSetDevice(deviceId));
    ACL_CHECK(aclrtGetDeviceInfo(deviceId, ACL_DEV_ATTR_CUBE_CORE_NUM, &availableCoreNum));
    if (availableCoreNum <= 0) {
        return 1;
    }
    ACL_CHECK(aclrtCreateStream(&stream));

    int64_t x1_0_shape[] = {1, 1, 32};
    TensorInfo x1_tensors[] = {{x1_0_shape, 3, 1}};
    TensorGroupInfo info_x1 = {x1_tensors, 1};
    int64_t x2_0_shape[] = {1, 32, 1};
    TensorInfo x2_tensors[] = {{x2_0_shape, 3, 1}};
    TensorGroupInfo info_x2 = {x2_tensors, 1};
    int64_t y_0_shape[] = {1};
    TensorInfo y_tensors[] = {{y_0_shape, 1, 0}};
    TensorGroupInfo info_y = {y_tensors, 1};

    bool transposeX1 = false;
    bool transposeX2 = false;

    uint8_t *inputHost_x1 = nullptr, *inputDevice_x1 = nullptr;
    uint8_t *inputHost_x2 = nullptr, *inputDevice_x2 = nullptr;

    uint8_t *outputHost_y = nullptr, *outputDevice_y = nullptr;

    ACL_CHECK(aclrtMallocHost((void **)&inputHost_x1, 64));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_x1, 64, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/x1.bin", 64, inputHost_x1, 64));
    ACL_CHECK(aclrtMemcpy(inputDevice_x1, 64, inputHost_x1, 64, ACL_MEMCPY_HOST_TO_DEVICE));
    ACL_CHECK(aclrtMallocHost((void **)&inputHost_x2, 64));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_x2, 64, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/x2.bin", 64, inputHost_x2, 64));
    ACL_CHECK(aclrtMemcpy(inputDevice_x2, 64, inputHost_x2, 64, ACL_MEMCPY_HOST_TO_DEVICE));

    ACL_CHECK(aclrtMallocHost((void **)&outputHost_y, 4));
    ACL_CHECK(aclrtMalloc((void **)&outputDevice_y, 4, ACL_MEM_MALLOC_HUGE_FIRST));

    run_kernel((GM_ADDR)inputDevice_x1, info_x1, (GM_ADDR)inputDevice_x2, info_x2, (GM_ADDR)outputDevice_y, info_y, availableCoreNum, stream, transposeX1, transposeX2);
    auto sync_ret_ = aclrtSynchronizeStreamWithTimeout(stream, 3000);
    if (sync_ret_ != 0) { fprintf(stderr, "[ERROR] aclrtSynchronizeStreamWithTimeout failed, ret=%d\n", sync_ret_); return 1; }

    ACL_CHECK(aclrtMemcpy(outputHost_y, 4, outputDevice_y, 4, ACL_MEMCPY_DEVICE_TO_HOST));
    FILE_CHECK(WriteFile("./output/y.bin", outputHost_y, 4));

    if (inputDevice_x1) aclrtFree(inputDevice_x1);
    if (inputHost_x1) aclrtFreeHost(inputHost_x1);
    if (inputDevice_x2) aclrtFree(inputDevice_x2);
    if (inputHost_x2) aclrtFreeHost(inputHost_x2);
    if (outputDevice_y) aclrtFree(outputDevice_y);
    if (outputHost_y) aclrtFreeHost(outputHost_y);

    aclrtDestroyStream(stream);
    aclrtResetDevice(deviceId);
    aclFinalize();
    return 0;
}

import numpy as np
import sys
import os

try:
    from ml_dtypes import bfloat16
except ImportError:
    bfloat16 = None

# Per-case output specs: 1 cases
# Each spec: (name, dtype, rtol, atol, tol)
# tol = max fraction of elements allowed to mismatch (0.0 = strict)
case_output_specs = {
    0: [
        ("y", np.float32, 0.0001, 0.0001, 0.0001),
    ],
}

if bfloat16 is None:
    for _cid, _specs in case_output_specs.items():
        for _name, _dtype, _rtol, _atol, _tol in _specs:
            if _dtype is None:
                print(f"ERROR: bfloat16 dtype required for case {_cid} output '{_name}' but ml_dtypes is not installed.")
                print("Install with: pip install ml_dtypes")
                sys.exit(1)

def verify_result(output_path, golden_path, dtype, rtol, atol, tol=0.0):
    output = np.fromfile(output_path, dtype=dtype)
    golden = np.fromfile(golden_path, dtype=dtype)
    total_size = golden.size

    if output.size != golden.size:
        if output.size < golden.size:
            golden = golden[:output.size]
            print(f"WARNING: output {output.size} < golden {total_size} elements, truncated golden to match")
        else:
            print(f"FAILED: output has {output.size} elements, golden has {total_size} — size mismatch")
            return False

    missing = total_size - output.size

    if np.issubdtype(dtype, np.integer) or np.issubdtype(dtype, np.bool_):
        if missing == 0 and np.array_equal(output, golden):
            print(f"PASSED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
            return True
        else:
            diff = np.abs(output.astype(np.int64) - golden.astype(np.int64))
            errors = np.sum(output != golden) + missing
            error_rate = errors / total_size if total_size > 0 else 0.0
            if error_rate <= tol:
                print(f"PASSED (tol={tol}): {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
                print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%)")
                return True
            print(f"FAILED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
            print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
            print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
            return False

    cmp_output = output.astype(np.float32) if dtype == bfloat16 else output
    cmp_golden = golden.astype(np.float32) if dtype == bfloat16 else golden
    isclose = np.isclose(cmp_output, cmp_golden, rtol=rtol, atol=atol, equal_nan=True)
    errors = np.sum(~isclose) + missing
    error_rate = errors / total_size if total_size > 0 else 0.0
    diff = np.abs(cmp_output - cmp_golden)
    if error_rate <= tol:
        print(f"PASSED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
        if errors > 0:
            print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
        print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
        return True
    else:
        print(f"FAILED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
        print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
        print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
        return False

if __name__ == "__main__":
    try:
        case_id = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    except ValueError:
        print(f"Invalid case_id: {sys.argv[1] if len(sys.argv) > 1 else '(none)'}")
        sys.exit(1)
    if case_id not in case_output_specs:
        print(f"Unknown case_id {case_id}. Available: {sorted(case_output_specs.keys())}")
        sys.exit(1)

    output_dir = "output"
    all_pass = True
    specs = case_output_specs[case_id]
    if not specs:
        print(f"Case {case_id}: No outputs to verify (all optional) — PASS")
        sys.exit(0)
    for name, dtype, rtol, atol, tol in specs:
        output_path = os.path.join(output_dir, name + ".bin")
        golden_path = os.path.join(output_dir, "golden_" + name + ".bin")
        if not os.path.exists(output_path):
            print(f"FAILED: output {name}.bin not found")
            all_pass = False
            continue
        if not os.path.exists(golden_path):
            print(f"FAILED: golden_{name}.bin not found")
            all_pass = False
            continue
        if not verify_result(output_path, golden_path, dtype, rtol, atol, tol):
            all_pass = False
    sys.exit(0 if all_pass else 1)
